class NomTipoRetencion extends BaseNomTipoRetencion {

    /**
     * Obtener un listado de los datos de los tipos de retenciones.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de retenciones.
     */
    public static function obtenerListadoTiposRetencion($inicio, $limite) {

        //Devolviendo el listado de los tipos de retenciones en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomTipoRetencion')
				->orderBy('orden ASC')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray():
                $query->from('NomTipoRetencion')
				->orderBy('orden ASC')
                ->fetchArray();
        return $result;
    }
    
    /**
     * Obtener la cantidad total de tipos de retenciones.
     * 
     * @return int      Cantidad total de tipos de retenciones.
     */
    public static function obtenerCantidadTotalTiposRetencion() {

        //Devolviendo la cantidad total de tipos de retenciones.
        return Doctrine_Query::create()->select('COUNT(idtiporetencion) AS cantidad')
                        ->from('NomTipoRetencion')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el tipo de retencion dado el identificador.
     * 
     * @param $idtreten             Identificador del tipo de retencion.
	 *
     * @return NomTipoRetencion     Objeto tipo de retencion (clase del dominio).
     */
    public static function obtenerObjTipoRetencionDadoId($idtreten) {
        return Doctrine::getTable('NomTipoRetencion')->find($idtreten);
    }
	
	/**
     * Obtener todos los tipos de retenciones.
     * 
     * @return array    Listado de tipos de retenciones.
     */
	public static function obtenerTodosTiposRetenciones() {
        return Doctrine_Query::create()
                ->from('NomTipoRetencion')
				->where('fechafin is null or fechafin <= now()')
                ->orderBy('orden ASC')
                ->fetchArray();
    }
    
	
	/**
     * Obtener si existe un tipo de retenci�n a partir de la denominaci�n y la abreviatura.
     * 
	 * @param int $idtipor    		Identificador del tipo de retenci�n.
	 * @param string $abrev    	 	Abreviatura del tipo de retenci�n.
     * @param string $denom    	 	Denominaci�n del tipo de retenci�n.
	 *
     * @return boolean    			Si existe del tipo de retenci�n.
     */
    public static function existeTipoRetencion($idtipor, $abrev, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idtiporetencion) AS cantidad')
                        ->from('NomTipoRetencion');
		if($abrev){
			$query->addWhere("abreviatura ilike ?", $abrev);
		}
		if($denom){
			$query->addWhere("denominacion ilike ?", $denom);
		}				
		if($idtipor){
			$query->addWhere('idtiporetencion <> ?', $idtipor);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	 
	 public static function tieneLimite($tiporet) {

        //Devolviendo la cantidad total de tipos de retenciones.
        return Doctrine_Query::create()->select('saldolimite')
            ->from('NomTipoRetencion')
            ->where('idtiporetencion = ?', array($tiporet))
            ->fetchOne()
            ->saldolimite;
    }
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
/*********************************************VER DESDE AQUI*****************************************/	
    public static function existeDenominacionTipoRetencion($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomTipoRetencion p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
	  public static function obtenerDenomXId($idtiporetencion) {
        return Doctrine_Query::create()->select('p.denominacion AS denominacion')
                        ->from('NomTipoRetencion p')
                        ->where('p.idtiporetencion = ?', array($idtiporetencion))
                        ->fetchOne()
                        ->denominacion;
   }
   
     public static function existeAbreviaturaTipoRetencion($abreviatura,$idtiporetencion) {
        //Devolviendo la cantidad total de los salarios especificos.
       $query = Doctrine_Query::create();
       $query->from('NomTipoRetencion')
         ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
         ->andWhere("abreviatura ilike '$abreviatura'");
       if ($idtiporetencion) {
         $query->andWhere("idtiporetencion <> $idtiporetencion");
       }
       $result = $query->count();
       if ($result > 0) {
         return true;
       } else {
         return false;
       }
     }

    public static function existeAbreviatura($abreviatura) {
        //Devolviendo la abreviatura
        $query = Doctrine_Query::create();
        $query->from('NomTipoRetencion')
            ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
            ->andWhere("abreviatura ilike '$abreviatura'");
        $result = $query->count();
        if ($result > 0) {
            return true;
        } else {
            return false;
        }
    }

    public function findByIdOrDenom($denom, $idtiporetencion = false)
    {
        try {

            $query = Doctrine_Query::create();
            $query->from('NomTipoRetencion')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if ($idtiporetencion) {
                $query->andWhere("idtiporetencion <> $idtiporetencion");
            }
         // print_r($query->getSqlQuery());die;
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

    public static function obtenerRetencionesSinCuentasContables() {
        return Doctrine_Query::create()
            ->select('denominacion')
            ->from('NomTipoRetencion')
            ->where('cuentacontable is null')
            ->fetchArray();
    }

